import{_ as a,o as e,c as s,a5 as o}from"./chunks/framework.C1a7WKBV.js";const g=JSON.parse('{"title":"Agent 与 MCP","description":"从聊天到动手：理解 AI Agent 如何调用工具，以及 MCP 协议在其中的角色。","frontmatter":{"title":"Agent 与 MCP","description":"从聊天到动手：理解 AI Agent 如何调用工具，以及 MCP 协议在其中的角色。"},"headers":[],"relativePath":"concepts/agent-and-mcp.md","filePath":"concepts/agent-and-mcp.md","lastUpdated":1788838685000}'),i={name:"concepts/agent-and-mcp.md"};function n(l,t,r,d,h,p){return e(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="agent-与-mcp" tabindex="-1">Agent 与 MCP <a class="header-anchor" href="#agent-与-mcp" aria-label="Permalink to &quot;Agent 与 MCP&quot;">​</a></h1><p>前两篇讲的是&quot;和 AI 对话&quot;。2025 年以来最重要的变化是：AI 开始<strong>替你操作真实的软件</strong>——读写文件、执行命令、发请求、订机票。这一篇讲清楚背后的两个关键词：Agent 和 MCP。</p><h2 id="_1-agent-从-动嘴-到-动手" tabindex="-1">1. Agent：从&quot;动嘴&quot;到&quot;动手&quot; <a class="header-anchor" href="#_1-agent-从-动嘴-到-动手" aria-label="Permalink to &quot;1. Agent：从&quot;动嘴&quot;到&quot;动手&quot;&quot;">​</a></h2><p><strong>Agent（智能体）</strong> 是指能自主调用工具、分多步完成任务的 AI 系统。它和普通聊天的区别在于一个循环：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接收目标 → 思考下一步 → 调用工具 → 观察结果 → 继续思考 → …… → 完成任务</span></span></code></pre></div><p>举例：你让 Claude Code&quot;修复这个报错的测试&quot;。</p><ol><li>它读测试文件（工具：读文件）；</li><li>运行测试看到报错（工具：执行命令）；</li><li>定位并修改源码（工具：写文件）；</li><li>再跑一次测试确认通过。</li></ol><p>整个过程你可能只需要确认几次，其余它自己完成。<strong>模型提供&quot;思考&quot;，工具提供&quot;手脚&quot;</strong>——两者合起来才是 Agent。</p><h3 id="_1-1-工具调用是怎么实现的" tabindex="-1">1.1 工具调用是怎么实现的 <a class="header-anchor" href="#_1-1-工具调用是怎么实现的" aria-label="Permalink to &quot;1.1 工具调用是怎么实现的&quot;">​</a></h3><p>本质仍然是《大语言模型是什么》里讲的&quot;预测下一个 token&quot;，只是训练时模型学会了输出一种特殊格式，表示&quot;我需要调用某个工具&quot;：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read_file&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test/user.test.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Agent 框架（Claude Code、Codex CLI、Cursor 等）解析这条指令，真正去执行，把结果塞回上下文，再让模型继续。所以工具调用的可靠性，依然受模型能力和上下文窗口限制——Agent 不是魔法，只是被赋予了手脚的模型。</p><h2 id="_2-mcp-工具的-usb-接口" tabindex="-1">2. MCP：工具的&quot;USB 接口&quot; <a class="header-anchor" href="#_2-mcp-工具的-usb-接口" aria-label="Permalink to &quot;2. MCP：工具的&quot;USB 接口&quot;&quot;">​</a></h2><p>工具从哪来？早期每个 AI 应用都自己写一套工具集成，重复劳动且互不通用。<strong>MCP（Model Context Protocol，模型上下文协议）</strong> 由 Anthropic 在 2024 年底提出，目标是把这件事标准化。</p><p>一个类比：MCP 之于 AI 工具，就像 USB 之于外设。以前每个设备一个专用接口，现在统一插口——任何应用（Claude Code、Cursor、CC Switch……）都能连接任何 MCP 服务器提供的工具。</p><h3 id="_2-1-三个角色" tabindex="-1">2.1 三个角色 <a class="header-anchor" href="#_2-1-三个角色" aria-label="Permalink to &quot;2.1 三个角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>是什么</th><th>例子</th></tr></thead><tbody><tr><td>MCP 主机</td><td>使用工具的 AI 应用</td><td>Claude Code、Cursor</td></tr><tr><td>MCP 服务器</td><td>提供工具的进程</td><td>GitHub 服务器（提 PR、查 Issue）、文件系统服务器、数据库服务器</td></tr><tr><td>工具</td><td>服务器暴露的具体能力</td><td><code>create_pull_request</code>、<code>query_database</code></td></tr></tbody></table><h3 id="_2-2-对你的实际意义" tabindex="-1">2.2 对你的实际意义 <a class="header-anchor" href="#_2-2-对你的实际意义" aria-label="Permalink to &quot;2.2 对你的实际意义&quot;">​</a></h3><ol><li><strong>能力即插即用</strong>：给客户端加一个 MCP 服务器的配置，它立刻多出一组技能（例如连接你的内部文档库）。</li><li><strong>生态复用</strong>：别人写好的 MCP 服务器你可以直接用，不必为每个 AI 应用重复配置。</li><li><strong>安全边界更清晰</strong>：哪些工具、访问哪些资源，可以按服务器粒度控制。</li></ol><p>主流客户端（Claude Code、Codex、Cursor 等）都已支持 MCP 配置。在 Claude Code 里实际添加 MCP 服务器的操作步骤，见《<a href="/tips/claude-code-advanced">Claude Code 进阶玩法</a>》第 4 节。</p><h2 id="_3-agent-时代的使用心法" tabindex="-1">3. Agent 时代的使用心法 <a class="header-anchor" href="#_3-agent-时代的使用心法" aria-label="Permalink to &quot;3. Agent 时代的使用心法&quot;">​</a></h2><ol><li><strong>目标写得越清楚，Agent 走得越直</strong>。第三篇里讲的提示词方法在 Agent 场景同样适用，而且更关键——它要自主走很多步，起点偏一点，终点偏很多。</li><li><strong>给检查点</strong>。大任务让它在关键节点停下来汇报（&quot;先列出你打算改的文件，等我确认&quot;），比事后回滚便宜得多。</li><li><strong>验收仍然是你</strong>。Agent 会执行、会汇报&quot;完成&quot;，但正确性的最终判断在你。它跑通了测试，不代表产品逻辑对了。</li><li><strong>工具越多不等于越好</strong>。挂太多无关工具会稀释模型的注意力，按需挂载。</li></ol><h2 id="_4-从使用者走向构建者" tabindex="-1">4. 从使用者走向构建者 <a class="header-anchor" href="#_4-从使用者走向构建者" aria-label="Permalink to &quot;4. 从使用者走向构建者&quot;">​</a></h2><p>如果你只想使用现成工具，接下来去《<a href="/tools/selector">工具选择器</a>》选定客户端，再用《<a href="/tutorials/first-project">第一个 AI 编程项目</a>》走完交付闭环。</p><p>如果你要开发自己的 AI 产品，进入两个深入专题：</p><ul><li>《<a href="/development/">AI 应用开发</a>》讲模型网关、结构化输出、RAG、可靠性和评测；</li><li>《<a href="/agents/">Agent 工程</a>》讲运行时状态机、工具与 MCP、上下文记忆、轨迹评测和多 Agent 协作。</li></ul><p>入门阶段记住“模型 + 工具 + 循环”即可；工程阶段要继续追问：状态存在哪里、动作由谁授权、失败如何恢复、结果如何独立验收。</p>',27)])])}const c=a(i,[["render",n]]);export{g as __pageData,c as default};
